"<!DOCTYPE html>
<html lang=\"en\">
<head>
    <meta charset=\"UTF-8\">
    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">
    <title>3D Craft - Modern Voxel Sandbox</title>
    <!-- Tailwind CSS for UI -->
    <script src=\"https://cdn.tailwindcss.com\"></script>
    <!-- Three.js Library -->
    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js\"></script>
    <!-- FontAwesome Icons -->
    <link rel=\"stylesheet\" href=\"https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css\">
    <style>
        @import url('https://fonts.googleapis.com/css2?family=Press+Start+2P@COMMENT_BODY@family=Inter:wght@400;600;700@COMMENT_BODY@display=swap');

        body {
            margin: 0;
            overflow: hidden;
            user-select: none;
            -webkit-user-select: none;
            font-family: 'Inter', sans-serif;
            background-color: #090a0f;
        }

        .pixel-font {
            font-family: 'Press Start 2P', monospace;
        }

        /* HUD Crosshair */
        #crosshair {
            position: absolute;
            top: 50%;
            left: 50%;
            width: 16px;
            height: 16px;
            transform: translate(-50%, -50%);
            pointer-events: none;
            z-index: 20;
        }
        #crosshair::before, #crosshair::after {
            content: '';
            position: absolute;
            background: rgba(255, 255, 255, 0.85);
            box-shadow: 0 0 2px rgba(0, 0, 0, 0.8);
        }
        #crosshair::before {
            left: 7px;
            top: 0;
            width: 2px;
            height: 16px;
        }
        #crosshair::after {
            left: 0;
            top: 7px;
            width: 16px;
            height: 2px;
        }

        /* Hotbar Highlight */
        .hotbar-slot {
            transition: all 0.15s ease-in-out;
            border: 3px solid #374151;
            background: rgba(17, 24, 39, 0.75);
            backdrop-filter: blur(8px);
        }
        .hotbar-slot.active {
            border-color: #f59e0b;
            transform: scale(1.12);
            box-shadow: 0 0 15px rgba(245, 158, 11, 0.5);
            background: rgba(31, 41, 55, 0.9);
        }

        /* Instructions Overlay */
        #instructions-screen {
            background: radial-gradient(circle at center, rgba(17, 24, 39, 0.85) 0%, rgba(3, 7, 18, 0.95) 100%);
            backdrop-filter: blur(12px);
        }

        /* Custom Scrollbar */
        ::-webkit-scrollbar {
            width: 6px;
        }
        ::-webkit-scrollbar-track {
            background: rgba(0, 0, 0, 0.2);
        }
        ::-webkit-scrollbar-thumb {
            background: rgba(255, 255, 255, 0.2);
            border-radius: 3px;
        }
    </style>
</head>
<body class=\"w-screen h-screen overflow-hidden\">

    <!-- Game Canvas -->
    <div id=\"canvas-container\" class=\"w-full h-full\"></div>

    <!-- HUD Crosshair -->
    <div id=\"crosshair\"></div>

    <!-- Top Left Status HUD -->
    <div class=\"absolute top-4 left-4 z-20 flex flex-col gap-2 pointer-events-none\">
        <div class=\"bg-gray-900/80 backdrop-blur-md px-4 py-2 rounded-xl border border-gray-700/50 text-white flex items-center gap-3 shadow-lg\">
            <i class=\"fa-solid fa-cube text-amber-500 text-lg\"></i>
            <div>
                <div class=\"text-xs text-gray-400 font-semibold tracking-wider\">BLOCKS CREATED</div>
                <div id=\"stats-blocks\" class=\"text-sm font-bold text-gray-100\">0</div>
            </div>
        </div>
        <div class=\"bg-gray-900/80 backdrop-blur-md px-4 py-2 rounded-xl border border-gray-700/50 text-white flex items-center gap-3 shadow-lg\">
            <i class=\"fa-solid fa-location-crosshairs text-emerald-400 text-lg\"></i>
            <div>
                <div class=\"text-xs text-gray-400 font-semibold tracking-wider\">POSITION (X, Y, Z)</div>
                <div id=\"stats-pos\" class=\"text-xs font-mono text-emerald-

